module logic;
use model {Summary,Event};
use util {reverse};
record LedgerState {
 pending:List<Event>,
 balance:I64,
 rejected:I64,
 peak:I64,
 audit:List<I64>,
 locked:Bool
}

fn run(events:List<Event>,initial:I64)->Summary {
 let completed=fold(i in List::length(events),state:LedgerState=LedgerState {
  pending:events,balance:initial,rejected:0,peak:initial,
  audit:List::empty<I64>(),locked:false
 }) {
  let changed=match (List::head(state.pending)) {
   Credit(creditAmount)=>if creditAmount>=0 && creditAmount<=1000000 {
    LedgerState {...state,balance:state.balance+creditAmount}
   } else {
    LedgerState {...state,rejected:state.rejected+1}
   },
   Debit(debitAmount)=>if debitAmount>=0 && debitAmount<=1000000 && !state.locked && debitAmount<=state.balance {
    LedgerState {...state,balance:state.balance-debitAmount}
   } else {
    LedgerState {...state,rejected:state.rejected+1}
   },
   Lock=>LedgerState {...state,locked:true},
   Unlock=>LedgerState {...state,locked:false}
  };
  LedgerState {
   ...changed,
   pending:List::tail(state.pending),
   peak:if changed.balance>state.peak {changed.balance} else {state.peak},
   audit:List::prepend(changed.balance,state.audit)
  }
 };
 Summary {
  balance:completed.balance,rejected:completed.rejected,peak:completed.peak,
  audit:reverse(completed.audit)
 }
}

